def archive_decades(years):
    # Number of decades covered, measured in ten-year spans from the first recording
    first = min(years)
    last = max(years)
    return ((last - first) // 10) + (1 if first % 10 != 0 else 0)

def archive_decades(years):
    # Number of calendar decades from the earliest recording's to the latest's
    first = min(years)
    last = max(years)
    return ((last - first) // 10) + (1 if first % 10 != 0 else 0)
